async function names(){return await page.locator('.nm').allTextContents()}
async function rectOf(name){return await page.locator('#pl li').filter({has:page.locator('.nm', {hasText:name})}).boundingBox()}
console.log('start',await names());
// Pick up Picking and position above first row
let r=await rectOf('Picking'); let first=await rows.nth(0).boundingBox();
