// move Quality check after Packing by positioning within upper half of Credit check row
r=await rectOf('Quality check'); let credit=await rectOf('Credit check');
await page.mouse.move(r.x+20,r.y+r.height/2); await page.mouse.down(); await page.mouse.move(credit.x+100,credit.y-2,{steps:10}); await page.mouse.up(); await page.waitForTimeout(100); console.log('after quality',await names());
await browser.close();
EOF
